 try:
  d=json.load(urllib.request.urlopen(u,timeout=15)); print(\"\\nQUERY\",q)
  for x in d.get(\"results\",[]):
   idx=x.get(\"abstract_inverted_index\") or {}; words=[None]* (max((max(v) for v in idx.values()),default=-1)+1)
   for w,ps in idx.items():
    for p in ps: words[p]=w
   print(\"TITLE\",x.get(\"title\")); print(\"DOI\",x.get(\"doi\")); print(\"ABSTRACT\", \" \".join(w for w in words if w))
